// TEC-216 (F1-12a): unit list of an organization. Serial units come from
// unit_current_state, fixed barcodes from fixed_barcode_holdings (summed
// per unit); both narrowed on holder_org_id. Without a status filter the
// list holds the units counted as stock (available, placed); a status
// filter lists exactly that status.
// TEC-373 (DT-BE-5): statuses is any-of (empty: available + placed),
// barcode exact or barcode_prefix (LIKE, the caller escapes % and _),
// location_uuids any-of (fixed barcodes have no single location and drop
// out), updated_from / updated_before (exclusive) on the holding's last
// change. sort_key: product, barcode, status (unit flow rank), quantity,
// meters (remaining, empty last), updated_at; id is the tiebreak.
func (q *Queries) ListOrganizationStockUnitRows(ctx context.Context, arg ListOrganizationStockUnitRowsParams) ([]ListOrganizationStockUnitRowsRow, error) {
	rows, err := q.db.Query(ctx, listOrganizationStockUnitRows,
		arg.BrandID,
		arg.ProductID,
		arg.Statuses,
		arg.Barcode,
		arg.BarcodePrefix,
		arg.LocationUuids,
		arg.UpdatedFrom,
		arg.UpdatedBefore,
		arg.Uuids,
		arg.Q,
		arg.SortDesc,
		arg.SortKey,
		arg.OffsetCount,
		arg.LimitCount,
		arg.OrganizationID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOrganizationStockUnitRowsRow{}
	for rows.Next() {
		var i ListOrganizationStockUnitRowsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Barcode,
			&i.UnitKind,
			&i.Status,
			&i.InitialMeters,
			&i.RemainingMeters,
			&i.Quantity,
			&i.UpdatedAt,
			&i.ProductID,
			&i.ProductUuid,
			&i.Sku,
			&i.ProductName,
			&i.UnitType,
			&i.UsesFixedBarcode,
			&i.LocationUuid,
			&i.LocationCode,
			&i.LocationName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

